                    totalAttempts: 0,
                    modulesCorrectSet: [],
                    scoreHistory: [],
                    accuracyHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    moduleChoice: 0,
                    rootCauseChoice: 0,
                    actionChoice: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var moduleSelect = document.getElementById('moduleSelect');
            if (moduleSelect) decisions.moduleChoice = parseInt(moduleSelect.value);

            var rootCauseSelect = document.getElementById('rootCauseSelect');
            if (rootCauseSelect) decisions.rootCauseChoice = parseInt(rootCauseSelect.value);

            var actionSelect = document.getElementById('actionSelect');
            if (actionSelect) decisions.actionChoice = parseInt(actionSelect.value);

            if (!decisions.moduleChoice || decisions.moduleChoice < 1 || decisions.moduleChoice > 4) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_module_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.rootCauseChoice || decisions.rootCauseChoice < 1 || decisions.rootCauseChoice > 5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_rootcause_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.actionChoice || decisions.actionChoice < 1 || decisions.actionChoice > 5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_action_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var out = this._computeRound(state);
            return out;
        }

        // v2.0.0 model. Per field, credit 1 (the fix that removes the cause) or 0.5 (defensible but incomplete).
        // Outcome: what the plant actually avoids. A fix on the instance (correct transaction) closes today's
        // ticket but the cause stays, so the incident reopens two scenarios later. Escalating without a diagnosis
        // avoids nothing while the cost runs. Overriding the credit control in scenario 6 ships today, then the
        // exposure and the unconfigured alert both land at the close. The score combines diagnosis (60%) and outcome (40%).
        _credit(map, v) { return (map && map[v]) ? map[v] : 0; }

        _evalRound(idx, d) {
            var R = this.ROUNDS[idx], K = this.CREDIT[idx], C = R.costImpact, last = this.ROUNDS.length;
            var m = this._credit(K.mod, d.moduleChoice), rc = this._credit(K.root, d.rootCauseChoice), ac = this._credit(K.act, d.actionChoice);
            var pts = 15 * m + 20 * rc + 15 * ac;
            var flags = { moduleMiss: m === 0, instanceFix: false, creditOverride: false, escalated: false, invAdjust: false };
            var avoided = 0, charges = [], rnum = idx + 1;
            if (d.actionChoice === 5) {
                flags.escalated = true;
            } else if (idx === 5 && (d.actionChoice === 1 || d.actionChoice === 2) && d.rootCauseChoice !== 3) {
                flags.creditOverride = true;
                avoided = C;
                charges.push({ due: last, amt: 2 * C, from: rnum, kind: 'credit' });
            } else if (d.actionChoice === 2 && this._credit(K.act, 2) !== 1) {
                flags.instanceFix = true;
                if (idx === 2) flags.invAdjust = true;
                avoided = Math.round(0.8 * C);
                charges.push({ due: Math.min(rnum + 2, last), amt: avoided, from: rnum, kind: 'reopen' });
            } else {
                avoided = Math.round(C * ac * (rc > 0 ? 1 : 0.5) * (m > 0 ? 1 : 0.5));
            }
            return { r: rnum, m: m, rc: rc, ac: ac, pts: pts, avoided: avoided, charges: charges, flags: flags,
                     mod: d.moduleChoice, root: d.rootCauseChoice, act: d.actionChoice };
        }

        // Everything derived from the history plus this round, so undo then resubmit gives the same state.
        _aggregate(recs, uptoRound) {
            var pts = 0, avoided = 0, charged = 0, exposure = 0, landed = [], perfect = 0, mods = [];
            var self = this;
            recs.forEach(function (x) {
                pts += x.pts; avoided += x.avoided; exposure += self.ROUNDS[x.r - 1].costImpact;
                if (x.pts >= 50) perfect++;
                if (x.m > 0 && mods.indexOf(x.mod) === -1) mods.push(x.mod);
                x.charges.forEach(function (c) { if (c.due <= uptoRound) { charged += c.amt; landed.push(c); } });
            });
            var n = recs.length || 1;
            var acc = Math.max(0, Math.min(100, pts / (50 * n) * 100));
            var net = avoided - charged;
            var outc = exposure > 0 ? Math.max(0, Math.min(100, net / exposure * 100)) : 0;
            var comp = Math.round((0.6 * acc + 0.4 * outc) * 10) / 10;
            return { pts: pts, acc: acc, net: net, charged: charged, exposure: exposure, outcome: outc, composite: comp, landed: landed, perfect: perfect, mods: mods };
        }

        _recsFrom(history, beforePeriod) {
            var recs = [];
            (history || []).forEach(function (h) {
                var p = h && (h.period || (h.results && h.results.period));
                if (h && h.results && h.results.rec && (!beforePeriod || p < beforePeriod)) recs[h.results.rec.r - 1] = h.results.rec;
            });
            return recs.filter(Boolean);
        }

        _tierId(score) { return score >= 88 ? 'expert' : score >= 72 ? 'proficient' : score >= 50 ? 'developing' : 'beginner'; }

        _computeRound(state) {
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var rec = this._evalRound(roundIdx, d);
            var recs = this._recsFrom(state.history, roundIdx + 1).filter(function (x) { return x.r < rec.r; });
            recs.push(rec);
            var A = this._aggregate(recs, rec.r);
            var landedNow = A.landed.filter(function (c) { return c.due === rec.r; });
            var ds = state.domainState;
            ds.totalScore = A.pts;
            ds.maxPossibleScore = 50 * recs.length;
            ds.costAvoided = A.net;
            ds.correctModules = recs.filter(function (x) { return x.m > 0; }).length;
            ds.correctRootCauses = recs.filter(function (x) { return x.rc >= 1; }).length;
            ds.correctActions = recs.filter(function (x) { return x.ac >= 1; }).length;
            ds.totalAttempts = recs.length;
            ds.modulesCorrectSet = A.mods.slice();
            ds.scoreHistory = recs.map(function (x, i) { return recs.slice(0, i + 1).reduce(function (s, y) { return s + y.pts; }, 0); });
            var self = this;
            ds.accuracyHistory = recs.map(function (x, i) { return Math.round(self._aggregate(recs.slice(0, i + 1), x.r).acc); });
            ds.compositeHistory = recs.map(function (x, i) { return self._aggregate(recs.slice(0, i + 1), x.r).composite; });
            ds.outcomePct = Math.round(A.outcome);
            ds.reopened = A.landed.length;
            ds.performanceTier = this._tierId(A.composite);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: A.composite });

            this._renderFeedback(round, rec, landedNow);

            var self2 = this;
            var gradedPeriod = state.currentPeriod;
            setTimeout(function() {
                if (gradedPeriod < self2.ROUNDS.length) {
                    self2._updateBriefing({ currentPeriod: gradedPeriod + 1 }, true);
                }
                var moduleSelect = document.getElementById('moduleSelect');
                var rootCauseSelect = document.getElementById('rootCauseSelect');
                var actionSelect = document.getElementById('actionSelect');
                if (moduleSelect) moduleSelect.value = '';
                if (rootCauseSelect) rootCauseSelect.value = '';
                if (actionSelect) actionSelect.value = '';
            }, 500);

            var tt = this._tt();
            return {
                period: state.currentPeriod,
                scenarioTitle: tt(round.titleKey),
                moduleChoice: this.MODULE_NAMES[d.moduleChoice],
                rootCauseChoice: tt(this.ROOTCAUSE_KEYS[d.rootCauseChoice]),
                actionChoice: tt(this.ACTION_KEYS[d.actionChoice]),
                moduleCorrect: rec.m > 0 ? 1 : 0,
                rootCauseCorrect: rec.rc >= 1 ? 1 : 0,
                actionCorrect: rec.ac >= 1 ? 1 : 0,
                periodScore: rec.pts,
                costSaved: rec.avoided - landedNow.reduce(function (s, c) { return s + c.amt; }, 0),
                totalScore: A.pts,
                accuracyPct: Math.round(A.acc),
                outcomePct: Math.round(A.outcome),
                overallScore: A.composite,
                score: A.composite,
                rec: rec
            };
        }

        _tt() { return function (k) { return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k; }; }
        _eur(v) { var n = Math.round(v); return (n < 0 ? '−€' : '€') + Math.abs(n).toLocaleString(this._lang() === 'es' ? 'es-ES' : 'en-US'); }
        _lang() { try { if (window.vcI18n && window.vcI18n._lang) return window.vcI18n._lang; } catch (e) {} var h = document.documentElement && document.documentElement.lang; return (h || 'en').slice(0, 2); }
        _fill(s, o) { Object.keys(o).forEach(function (k) { s = s.split('{' + k + '}').join(o[k]); }); return s; }

        _renderFeedback(round, rec, landedNow) {
            var tt = this._tt(), self = this, K = this.CREDIT[rec.r - 1];
            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (!feedbackPanel || !feedbackText) return;
            feedbackPanel.style.display = 'block';
            feedbackPanel.className = 'erpcircuit-sim-feedback';
            var maxP = 50, fb = '', ptsTxt = String(rec.pts).replace('.', this._lang() === 'es' ? ',' : '.');
            if (rec.pts >= 40) { feedbackPanel.classList.add('erpcircuit-feedback-good'); fb += '<strong>✅ ' + this._fill(tt('fb_excellent'), { score: ptsTxt, max: maxP }) + '</strong><br><br>'; }
            else if (rec.pts >= 20) { feedbackPanel.classList.add('erpcircuit-feedback-partial'); fb += '<strong>⚠️ ' + this._fill(tt('fb_partial'), { score: ptsTxt, max: maxP }) + '</strong><br><br>'; }
            else { feedbackPanel.classList.add('erpcircuit-feedback-wrong'); fb += '<strong>❌ ' + this._fill(tt('fb_incorrect'), { score: ptsTxt, max: maxP }) + '</strong><br><br>'; }
            var best = function (map) { var b = 0, k; for (k in map) { if (map[k] === 1) { b = parseInt(k, 10); break; } } return b; };
            var line = function (label, credit, chosenTxt, bestTxt) {
                var mark = credit >= 1 ? '✅' : credit > 0 ? '◐' : '❌';
                var tail = credit >= 1 ? ' (' + tt('fb_correct') + ')' : credit > 0 ? ' — ' + tt('fb_partial_credit') + ' ' + bestTxt : ' — ' + tt('fb_correct_answer') + ' ' + bestTxt;
                return '<strong>' + tt(label) + '</strong> ' + mark + ' ' + tt('fb_you_selected') + ' ' + chosenTxt + tail + '<br>';
            };
            fb += line('fb_module_label', rec.m, this.MODULE_NAMES[rec.mod], this.MODULE_NAMES[best(K.mod)]);
            fb += line('fb_rootcause_label', rec.rc, tt(this.ROOTCAUSE_KEYS[rec.root]), tt(this.ROOTCAUSE_KEYS[best(K.root)]));
            fb += line('fb_action_label', rec.ac, tt(this.ACTION_KEYS[rec.act]), tt(this.ACTION_KEYS[best(K.act)]));
            fb += '<br><strong>' + tt('fb_explanation_label') + '</strong> ' + tt(round.explanationKey);
            if (rec.flags.escalated) fb += '<br><br>⏳ ' + tt('fb_escalated');
            if (rec.avoided > 0) fb += '<br><br>💶 <strong>' + tt('fb_cost_avoided') + '</strong> ' + this._eur(rec.avoided);
            landedNow.forEach(function (c) {
                fb += '<br><br>🔁 <strong>' + self._fill(tt(c.kind === 'credit' ? 'fb_landed_credit' : 'fb_landed_reopen'), { n: c.from, amt: self._eur(c.amt) }) + '</strong>';
            });
            feedbackText.innerHTML = fb;
            feedbackText.setAttribute('data-eqil-round', String(rec.r));
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.totalScore',
