        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var recs = this._recsFrom(history, 0);
            if (!recs.length) return {};
            var tt = this._tt(), self = this;
            var last = recs[recs.length - 1].r;
            var A = this._aggregate(recs, last);
            var tier = this._tierId(A.composite);
            var listOf = function (pred) { return recs.filter(pred).map(function (x) { return x.r; }); };
            var join = function (a) { return a.join(', '); };
            var insights = [];
            var mm = listOf(function (x) { return x.flags.moduleMiss; });
            var inst = listOf(function (x) { return x.flags.instanceFix; });
            var esc = listOf(function (x) { return x.flags.escalated; });
            var cred = listOf(function (x) { return x.flags.creditOverride; });
            var inv = listOf(function (x) { return x.flags.invAdjust; });
            if (mm.length) insights.push(this._fill(tt('ins_module_miss'), { list: join(mm) }));
            if (inst.length) insights.push(this._fill(tt('ins_instance_fix'), { list: join(inst) }));
            if (inv.length) insights.push(tt('ins_inv_adjust'));
            if (cred.length) insights.push(tt('ins_credit_override'));
            if (esc.length) insights.push(this._fill(tt('ins_escalated'), { n: esc.length, list: join(esc) }));
            if (!mm.length && !inst.length && !esc.length && !cred.length) insights.push(this._fill(tt('ins_clean'), { n: recs.filter(function (x) { return x.m > 0 && x.rc >= 1; }).length }));
            insights.push(A.composite >= 88 ? tt('insight_high') : A.composite >= 60 ? tt('insight_mid') : tt('insight_low'));
            // turning point: the scenario where the most money was lost against what it put at risk
            var worst = null, worstLoss = -1;
            recs.forEach(function (x) {
                var C = self.ROUNDS[x.r - 1].costImpact;
                var lost = C - x.avoided + x.charges.reduce(function (s, c) { return s + (c.due <= last ? c.amt : 0); }, 0);
                if (lost > worstLoss) { worstLoss = lost; worst = x; }
            });
            var turning = (worst && worstLoss > 0)
                ? this._fill(tt('turning_point'), { n: worst.r, title: tt(this.ROUNDS[worst.r - 1].titleKey), amt: this._eur(worstLoss), pts: String(worst.pts).replace('.', this._lang() === 'es' ? ',' : '.') })
                : tt('turning_none');
            var perfectRounds = A.perfect;
            return {
                totalScore: A.pts,
                maxScore: recs.length * 50,
                avgScore: Math.round(A.pts / recs.length),
                accuracyPct: Math.round(A.acc),
                outcomePct: Math.round(A.outcome),
                totalCostSaved: A.net,
                reopened: A.landed.length,
                perfectRounds: perfectRounds,
                composite: A.composite,
                overallScore: A.composite,
                score: A.composite,
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: tt('tier_' + tier),
                turningPoint: turning,
                questions: [tt('dq_1'), tt('dq_2'), tt('dq_3')],
                insights: insights
            };
        }

